  root.hidden=false;const total=baseline.primaryTotal==null?baseline.range.minimum+'–'+baseline.range.maximum:baseline.primaryTotal;score.textContent='Исходная диагностика: '+total+' из '+baseline.maximum+'. Показано завершённых попыток: '+safeSummary.displayedAttempts+'.';const predicted=baseline.forecast.score==null?baseline.forecast.range.minimum+'–'+baseline.forecast.range.maximum:baseline.forecast.score;forecast.textContent=baseline.forecast.label+': '+predicted+'. '+presentPublicBrand(EGE_MOCK_FORECAST_METADATA.disclaimer)+' · '+baseline.forecast.policyId;
