function adaptiveOverviewAuthority(){try{const generation=window.EasyBoostSync?.ownerBoundGeneration?.(currentUser);
  return currentUser&&Number.isSafeInteger(generation)?{owner:currentUser,ownerGeneration:generation}:null}catch(_){return null}}
function adaptiveOverviewOwner(){return adaptiveOverviewAuthority()?.owner||null}
function adaptiveOverviewGeneration(){return adaptiveOverviewAuthority()?.ownerGeneration??0}
function sameAdaptiveOwner(a,b){return Boolean(a&&b&&a.owner===b.owner&&a.ownerGeneration===b.ownerGeneration)}
function beginAdaptiveView(){const next=adaptiveOverviewAuthority();if(!sameAdaptiveOwner(next,adaptiveViewAuthority)){if(adaptiveViewAuthority)clearAdaptivePrivateUi(adaptiveViewAuthority);adaptiveViewAuthority=next?{...next}:null}adaptiveViewToken+=1;return next?Object.freeze({...next,viewToken:adaptiveViewToken}):null}
function captureAdaptiveAuthority(){const authority=adaptiveOverviewAuthority();return authority&&sameAdaptiveOwner(authority,adaptiveViewAuthority)?Object.freeze({...authority,viewToken:adaptiveViewToken}):null}
function adaptiveAuthorityCurrent(authority){if(!authority)return false;const current=adaptiveOverviewAuthority();return Boolean(current&&sameAdaptiveOwner(current,authority)&&sameAdaptiveOwner(adaptiveViewAuthority,authority)&&authority.viewToken===adaptiveViewToken)}
function commitAdaptiveUi(authority,commit){if(!adaptiveAuthorityCurrent(authority))return false;commit();return true}
function adaptiveOwnerHeaders(authority){return{headers:{'X-EasyBoost-Expected-Owner':authority.owner}}}
function adaptivePayloadOwned(payload,authority){return Boolean(payload&&authority&&apiResponseOwner(payload)===authority.owner&&adaptiveAuthorityCurrent(authority))}
function adaptiveOwnerHeader(authority){return{'X-EasyBoost-Expected-Owner':authority.owner}}
function adaptiveOwnerError(){return Object.assign(new Error('adaptive owner changed'),{code:'OWNER_CHANGED',status:409})}
async function invalidateAdaptiveAuthority(authority){return invalidateLearningAuthority(authority)}
async function adaptiveBoundRequest(request,authority){try{const result=await request();if(!adaptivePayloadOwned(result,authority))throw adaptiveOwnerError();return result}catch(error){if(apiIsAuthorityFailure(error))await invalidateAdaptiveAuthority(authority);throw error}}
async function adaptiveGet(path,authority=captureAdaptiveAuthority()){if(!adaptiveAuthorityCurrent(authority))throw adaptiveOwnerError();
  return adaptiveBoundRequest(function(){return apiGet(path,adaptiveOwnerHeaders(authority))},authority)}
async function adaptivePost(path,body,authority=captureAdaptiveAuthority()){if(!adaptiveAuthorityCurrent(authority))throw adaptiveOwnerError();
  return adaptiveBoundRequest(function(){return apiPost(path,body,adaptiveOwnerHeader(authority))},authority)}
async function adaptivePostIdempotent(path,body,key,authority=captureAdaptiveAuthority()){if(!adaptiveAuthorityCurrent(authority))throw adaptiveOwnerError();
  return adaptiveBoundRequest(function(){return apiPostIdempotent(path,body,key,adaptiveOwnerHeader(authority))},authority)}
async function adaptivePut(path,body,headers,authority=captureAdaptiveAuthority()){if(!adaptiveAuthorityCurrent(authority))throw adaptiveOwnerError();
  return adaptiveBoundRequest(function(){return apiPut(path,body,headers)},authority)}
function setAdaptiveReadOnly(readOnly){const root=document.getElementById('adaptive_plan');if(!root)return;root.dataset.mode=readOnly?'offline_read_only':'online';if(!readOnly){root.querySelectorAll('[data-adaptive-readonly-disabled="true"]').forEach(function(control){control.disabled=false;delete control.dataset.adaptiveReadonlyDisabled});return}root.querySelectorAll('input,select,textarea,button').forEach(function(control){if(!control.disabled){control.disabled=true;control.dataset.adaptiveReadonlyDisabled='true'}})}
function adaptiveCommercialMessage(error){return presentCommercialError(error,apiMessage(error,'request'))}
function showAdaptivePaywall(message){const paywall=document.getElementById('adaptive_paywall');const copy=document.getElementById('adaptive_paywall_copy');if(!paywall||!copy)return;paywall.hidden=false;if(message)copy.textContent=message}
function applyPreferredAdaptiveSessionDuration(){
  const preferred=profileModule.studyPreferences(S&&S.learnerPreferences).preferredSessionMinutes;
  const inputs=Array.from(document.querySelectorAll('input[name="adaptive_session_duration"]'));
  const matching=inputs.find(function(input){return Number(input.value)===preferred});
  const custom=document.getElementById('adaptive_session_custom');
  inputs.forEach(function(input){input.checked=false});
  if(matching){matching.checked=true;if(custom)custom.value=''}
  else if(custom)custom.value=String(preferred);
}
function applyAdaptiveDurationAccess(){const access=adaptiveAccessState;if(!access)return;const limited=access.tier==='free';const used=Boolean(access.usage&&access.usage.demoSessionUsed);const locked=limited&&used;const custom=document.getElementById('adaptive_session_custom');const preview=document.getElementById('adaptive_session_preview');const help=document.getElementById('adaptive_session_duration_help');document.querySelectorAll('input[name="adaptive_session_duration"]').forEach(function(input){if(limited&&input.value==='15'&&!used)input.checked=true;else if(limited)input.checked=false;input.disabled=locked||(limited&&input.value!=='15')});if(custom){custom.disabled=limited;custom.value=limited?'':custom.value}if(help)help.textContent=limited?(used?'Новые занятия не входят в выданный доступ. Обратитесь к оператору.':'Сейчас доступно занятие на 15 минут. Для изменения доступа обратитесь к оператору.'):'От 15 до 120 минут, шаг 5 минут. Начальное значение — сохранённое предпочтение.';if(preview)preview.disabled=locked}
function drawAdaptiveAccess(access){if(!access)return;adaptiveAccessState=access;const presentation=presentPublicPlan(access);const panel=document.getElementById('adaptive_access');const title=document.getElementById('adaptive_access_title');const copy=document.getElementById('adaptive_access_copy');const paywall=document.getElementById('adaptive_paywall');const deep=document.getElementById('adaptive_deep_diagnostic_start');const report=document.getElementById('adaptive_detailed_report');const form=document.getElementById('adaptive_goal_form');if(panel){panel.dataset.tier=presentation.id}if(title)title.textContent=presentation.label;if(copy)copy.textContent=presentation.summary;if(deep)deep.hidden=!(access.capabilities&&access.capabilities.deepDiagnostic);if(report){report.dataset.locked=String(!(access.capabilities&&access.capabilities.detailedReports));report.textContent=access.capabilities&&access.capabilities.detailedReports?'Открыть подробный отчёт':'Подробный отчёт · недоступен'}if(paywall)paywall.hidden=!(access.tier==='free'&&access.usage&&access.usage.demoSessionUsed);if(form){const locked=access.tier==='free'&&access.usage&&access.usage.demoSessionUsed;form.querySelectorAll('input,button').forEach(function(control){control.disabled=locked})}applyAdaptiveDurationAccess()}
function drawAdaptiveForecast(plan){
  const section=document.getElementById('adaptive_forecast');const range=document.getElementById('adaptive_forecast_range');const confidence=document.getElementById('adaptive_forecast_confidence');const allocation=document.getElementById('adaptive_weekly_allocation');const choices=document.getElementById('adaptive_plan_choices');if(!section||!range||!confidence||!allocation||!choices)return;
  if(!plan||!plan.forecast||!plan.allocation){section.hidden=true;allocation.replaceChildren();choices.replaceChildren();return}
  section.hidden=false;const forecast=plan.forecast;
  if(forecast.status==='exam_date_expired'){range.textContent='Дата экзамена уже наступила. Обновите дату цели, чтобы построить новый прогноз.';confidence.textContent='Прогноз баллов и недельное распределение не рассчитываются для прошедшей даты.';allocation.replaceChildren();choices.replaceChildren();choices.appendChild(text('div','Обновить дату экзамена в цели','border-left:3px solid #F2683F;padding-left:8px;font-weight:700;font-size:10.5px;line-height:1.4;color:#3E4248;'));return}
  range.textContent='Ориентир: '+plan.forecast.lowScore+'–'+plan.forecast.highScore+' баллов. Для цели нужно около '+forecast.requiredWeeklyMinutes+' минут в неделю.';
  confidence.textContent='Уверенность прогноза '+forecast.confidence+'%. Это диапазон, а не обещание результата; расчёт уточняется по новым самостоятельным ответам.';
  allocation.replaceChildren();(plan.allocation.modules||[]).slice().sort(function(first,second){return second.percentage-first.percentage}).forEach(function(module){const reasons=Array.isArray(module.reasonCodes)?module.reasonCodes.map(function(code){return adaptiveReasonLabels[code]||code}).slice(0,2):[];const row=document.createElement('div');row.setAttribute('style','display:flex;justify-content:space-between;gap:10px;border-top:1px solid #E9E5DE;padding-top:6px;');row.appendChild(text('span',adaptiveModuleLabel(module.id)+(reasons.length?' — '+reasons.join(', '):''),'font-weight:650;font-size:10.5px;line-height:1.35;color:#52565E;'));row.appendChild(text('strong',module.percentage+'%','flex:none;font-weight:800;font-size:11px;color:#B54E2F;'));allocation.appendChild(row)});
  choices.replaceChildren();(forecast.choices||[]).forEach(function(choice){let label='';if(choice.type==='increase_weekly_time')label=choice.constraintCode==='maximum_supported_weekly_time'?'Поставить '+choice.weeklyMinutes+' минут в неделю и скорректировать цель':'Увеличить время до '+choice.weeklyMinutes+' минут в неделю';else if(choice.type==='adjust_target_score')label='Скорректировать цель до '+choice.targetScore+' баллов';else if(choice.type==='update_exam_date')label='Выбрать новую дату экзамена';if(!label)return;const button=text('button',label);button.type='button';button.className='adaptive-action adaptive-action--quiet';button.addEventListener('click',function(){if(choice.type==='increase_weekly_time'){document.getElementById('adaptive_weekly_minutes').value=choice.weeklyMinutes;document.getElementById('adaptive_weekly_minutes').focus()}else if(choice.type==='adjust_target_score'){document.getElementById('adaptive_target_score').value=choice.targetScore;document.getElementById('adaptive_target_score').focus()}else document.getElementById('adaptive_exam_date').focus()});choices.appendChild(button)});
}

function adaptiveDiagnosticDue(payload){return Boolean(payload&&((payload.profile&&payload.profile.needsDiagnostic)||(payload.retention&&payload.retention.rediagnostic&&payload.retention.rediagnostic.due)))}

function drawAdaptivePlan(payload){
  const root=document.getElementById('adaptive_plan');const summary=document.getElementById('adaptive_plan_summary');if(!root||!summary)return;
  const goal=payload&&payload.goal;const profile=payload&&payload.profile?payload.profile:{};
  drawAdaptiveAccess(payload&&payload.access);
  if(goal){document.getElementById('adaptive_target_score').value=goal.targetScore;document.getElementById('adaptive_exam_date').value=goal.examDate;document.getElementById('adaptive_weekly_minutes').value=goal.weeklyMinutes}
  const observed=Math.max(0,Number(profile.evidenceCount)||0);const confidence=Math.max(0,Number(profile.confidence)||0);
  const skillCount=Array.isArray(profile.skills)&&profile.skills.length?profile.skills.length:21;const establishedSkillCount=Math.max(0,Math.min(skillCount,Number(profile.establishedSkillCount)||0));
  const modules=Array.isArray(profile.modules)?profile.modules.filter(function(module){return module.evidenceCount>0}).sort(function(first,second){return first.mastery-second.mastery}):[];
  const weakest=modules[0];const state=establishedSkillCount===skillCount&&!profile.preliminary?'Профиль подтверждён':'Профиль предварительный';
  const scheduled=Boolean(payload&&payload.retention&&payload.retention.rediagnostic&&payload.retention.rediagnostic.due&&!profile.needsDiagnostic);const diagnostic=profile.needsDiagnostic?' Нужна короткая диагностика для уточнения.':scheduled?' Пора обновить короткую диагностику; занятия остаются доступны.':'';
  const assisted=Number(profile.assistedEvidenceCount)>0&&establishedSkillCount<skillCount?' Результаты с подсказкой не подтверждают владение навыком.':'';
  summary.textContent=state+' · подтверждено навыков: '+establishedSkillCount+' из '+skillCount+' · уверенность '+confidence+'% · данных: '+observed+'.'+(weakest?' Сейчас важнее всего: '+weakest.id+' ('+weakest.mastery+'%).':'')+assisted+diagnostic;
  const focusNode=document.getElementById('adaptive_grammar_focus');const recommendation=payload&&payload.grammarRecommendation;const focus=recommendation&&recommendation.pointer;
  if(focusNode){focusNode.hidden=!focus;if(focus){const topic=GRAMMAR_CATALOG.topics[focus.topicId];const errorLabels={construction_choice:'выбор конструкции',word_or_verb_form:'форма слова или глагола',auxiliary:'вспомогательный глагол',agreement:'согласование',word_order:'порядок слов',negation_or_question:'отрицание или вопрос',confusion_pair:'пара похожих конструкций'};const pair=focus.confusionPair?' · '+focus.confusionPair.replace('__',' ↔ ').replaceAll('_',' '):'';const early=focus.earlyPractice?' · ранняя практика из-за близкого экзамена, без досрочного повышения стадии':'';focusNode.textContent='Точный фокус грамматики: '+(topic&&topic.n||'тема '+focus.topicId)+' · '+(errorLabels[focus.errorCode]||focus.errorCode)+pair+early}}
  drawAdaptiveForecast(payload&&payload.plan);
  const access=payload&&payload.access||adaptiveAccessState;const start=document.getElementById('adaptive_diagnostic_start');if(start)start.hidden=!adaptiveDiagnosticDue(payload)||!(access&&access.capabilities&&access.capabilities.shortDiagnostic);
}

