  const root=document.getElementById('adaptive_plan');if(root)root.querySelectorAll('input,select,textarea,button').forEach(function(control){control.disabled=false;delete control.dataset.adaptiveReadonlyDisabled});
  drawProgressNarrative(null,{source:'unavailable'});drawEvidenceProgressSummary(null,{source:'unavailable',unavailable:true});drawEgeMockDashboard(null);setAdaptiveReadOnly(true);
