async function renderRecoveryMap(){const root=document.getElementById('voice_recovery_map');if(!root)return;const recoveryAuthority=captureAdaptiveAuthority();if(!recoveryAuthority)return;try{const payload=await adaptiveGet('/api/v1/voice-tutor/recovery-map',recoveryAuthority);drawRecoveryMap(payload)}catch(error){if(!adaptiveAuthorityCurrent(recoveryAuthority))return;root.replaceChildren(text('div','Карта освоенных ошибок','font-weight:800;font-size:15px;color:#2B2B2B;'),text('div',apiMessage(error,'request'),'margin-top:8px;font-weight:600;font-size:12px;color:#6A6E75;'))}}

